let scanWorker=null,scanLanguage='',scanProgress=()=>{};
async function ocrWorker(language='chi_sim'){
  if(scanWorker){if(scanLanguage!==language){await scanWorker.reinitialize(language,1);scanLanguage=language;}return scanWorker;}
  if(!window.Tesseract)loadEmbeddedScript('tesseract.min.js');
  const languages={chi_sim:embeddedAssets['chi_sim.traineddata.gz'],eng:embeddedAssets['eng.traineddata.gz']};
  const shim=`const offlineLanguages=${JSON.stringify(languages)};const nativeFetch=self.fetch;self.fetch=(url,...args)=>{const match=String(url).match(/(chi_sim|eng)\\.traineddata(?:\\.gz)?$/);if(match)return Promise.resolve(new Response(Uint8Array.from(atob(offlineLanguages[match[1]]),c=>c.charCodeAt(0))));if(/^(blob:|data:)/.test(String(url)))return nativeFetch(url,...args);return Promise.reject(new Error('识别组件只允许离线资源'));};\n`;
  const code=assetText('core.wasm.js')+'\n'+shim+assetText('worker.min.js');
  scanWorker=await Tesseract.createWorker(language,1,{workerPath:objectURL(code),workerBlobURL:false,langPath:'offline',cacheMethod:'none',logger:m=>scanProgress(m),errorHandler:()=>{}});
  scanLanguage=language;await scanWorker.setParameters({tessedit_pageseg_mode:'3',preserve_interword_spaces:'1',user_defined_dpi:'300'});return scanWorker;
}
function extractFields(text,columns,fileName=''){
  const clean=text.replace(/[：﹕]/g,':').replace(/([\u3400-\u9fff]) +(?=[\u3400-\u9fff])/g,'$1');
  const aliases={'车号':['车牌号码','车牌号','车牌','车辆号','车辆号码'],'货运公司':['承运公司','承运单位','运输公司'],'建单日期':['制单日期','开单日期'],'卸货日期':['到货日期','收货日期','收货时间'],'吨位':['结算吨位','净重','实收重量','结算重量'],'单价':['运费单价','运输单价'],'金额':['运费金额','运输金额'],'其它费用':['其他费用','附加费'],'总金额':['合计金额','运费合计'],'到货单位':['收货单位','收货公司'],'发货单位':['发货公司','发货人'],'始发地':['发货地','起运地'],'目的地':['收货地','到货地']};
  const escapeRx=t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),allLabels=[...new Set(columns.flatMap(c=>[c.name,...aliases[c.name]||[]]))].sort((a,b)=>b.length-a.length);
  const values={};
  for(const col of columns){let found='';for(const name of [col.name,...aliases[col.name]||[]]){const rx=new RegExp('(?:^|[\\s|])'+escapeRx(name)+'[ \\t]*:?\\s*([^\\n]+)','m'),m=clean.match(rx);if(m){found=m[1].split(new RegExp('(?:'+allLabels.filter(n=>n!==name).map(escapeRx).join('|')+')\\s*:'))[0].trim();break;}}
    if(col.name==='车号'){const m=(found+' '+fileName+' '+clean).replace(/\s/g,'').toUpperCase().match(/[京津沪渝冀豫云辽黑湘皖鲁新苏浙赣鄂桂甘晋蒙陕吉闽贵粤青藏川宁琼][A-Z][A-Z0-9]{5,6}/);found=m?.[0]||'';}
    else if(col.type==='number'){const m=found.replace(/[,，]/g,'').match(/[-+]?\d+(?:\.\d+)?/);found=m?.[0]||'';}
    else if(col.type==='date'){const m=found.match(/\d{4}[年./-]\d{1,2}[月./-]\d{1,2}日?/);found=m?display(parseCell(m[0],'date')):'';}
    else found=found.replace(/^[|:]+|[|]+$/g,'').trim();
    values[col.id]=found;
  }
  return values;
}
async function scanDialog(){
  if(!active)return;let doc=null,frame=null,index=0,recognizing=false,generation=0,closed=false;
  const dispose=()=>{closed=true;generation++;doc?.close();window.scanDraftDirty=false;scanProgress=()=>{};};
  modal('扫描录入',`<div class="document-toolbar"><label class="button small solid" for="scan-file">＋ 导入图片 / PDF</label><input type="file" id="scan-file" accept=".png,.jpg,.jpeg,.webp,.bmp,.pdf" hidden><select id="scan-page" aria-label="扫描页码" disabled><option>第 1 页</option></select><button type="button" class="button small" id="scan-rotate" disabled>旋转 90°</button><select id="scan-language" aria-label="识别语言"><option value="chi_sim">中文优先</option><option value="chi_sim+eng">中英混排</option></select><button type="button" class="button small primary" id="scan-recognize" disabled>识别本页</button><span id="scan-progress" class="muted">本机离线识别</span></div><div class="scan-layout"><div class="scan-left"><div class="document-preview" id="scan-preview"><div class="empty-state"><div class="empty-icon">▧</div><strong>放入一张单据</strong><p>支持图片、扫描 PDF，可逐页录入。</p></div></div><label class="modal-field"><span>识别文字 · 可选中文字后点击右侧字段名填入</span><textarea id="scan-text" rows="6" placeholder="识别结果将显示在这里"></textarea></label><button type="button" id="scan-rematch" class="text-button">按文字重新匹配字段</button></div><div><div class="scan-review-heading">核对后写入表格 <span id="scan-matched"></span></div><div class="scan-fields">${active.columns.map(c=>`<label class="modal-field"><button type="button" data-scan-label="${c.id}" title="填入左侧选中的文字">${h(c.name)}</button><input data-scan-field="${c.id}" type="text" value=""></label>`).join('')}</div></div></div>`,'确认新增一条记录',()=>{
    if(recognizing)throw new Error('请等待识别完成。');const entries=[...document.querySelectorAll('[data-scan-field]')];if(entries.every(el=>!el.value.trim()))throw new Error('请先识别或填写要录入的数据。');
    const row=freshRow();for(let i=0;i<active.columns.length;i++){const input=entries.find(el=>el.dataset.scanField===active.columns[i].id),text=input?.value.trim();if(text){row.cells[i]=parseCell(text,active.columns[i].type);if(active.columns[i].computed)row.cells[i].manual=true;}}
    active.rows.push(row);recalculateAll(active);view='edit';page=Math.ceil(active.rows.length/pageSize);changed();renderData();dispose();closeModal(false);toast('已新增 1 条记录，请点击保存写入本地文件。');
  },dispose);$('modal').classList.add('scan-modal');$('modal-submit').disabled=true;
  function review(text){$('scan-text').value=text;const fields=extractFields(text,active.columns,doc?.name||'');for(const el of document.querySelectorAll('[data-scan-field]'))el.value=fields[el.dataset.scanField]||'';$('scan-matched').textContent=Object.values(fields).filter(Boolean).length+' 个候选字段';window.scanDraftDirty=!!text.trim();$('modal-submit').disabled=false;}
  async function showPage(){const seq=++generation;$('scan-progress').textContent='正在打开文件…';frame=await doc.page(index);if(closed||seq!==generation)return;$('scan-preview').replaceChildren(frame.canvas);$('scan-recognize').disabled=false;$('scan-rotate').disabled=false;$('scan-progress').textContent=doc.name;}
  $('scan-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{doc?.close();doc=await openLocalDocument(file);index=0;$('scan-page').innerHTML=Array.from({length:doc.count},(_,i)=>`<option value="${i}">第 ${i+1} / ${doc.count} 页</option>`).join('');$('scan-page').disabled=doc.count<=1;await showPage();}catch(e){toast(e.message,true);}};
  $('scan-page').onchange=async e=>{if(window.scanDraftDirty&&!confirm('切换页面会清空当前识别草稿，继续吗？')){e.target.value=index;return;}index=Number(e.target.value);review('');await showPage();};
  $('scan-rotate').onclick=()=>{if(!frame||recognizing)return;const old=frame.canvas,canvas=document.createElement('canvas');canvas.width=old.height;canvas.height=old.width;const ctx=canvas.getContext('2d');ctx.translate(canvas.width,0);ctx.rotate(Math.PI/2);ctx.drawImage(old,0,0);frame.canvas=canvas;frame.rotated=true;$('scan-preview').replaceChildren(canvas);};
  $('scan-recognize').onclick=async()=>{if(!frame||recognizing)return;recognizing=true;$('scan-recognize').disabled=true;$('scan-file').disabled=true;$('scan-page').disabled=true;$('modal-submit').disabled=true;scanProgress=m=>{if(!closed)$('scan-progress').textContent=(m.status==='recognizing text'?'正在识别 ':'准备识别 ')+Math.round((m.progress||0)*100)+'%';};try{let text='';if(frame.pdfPage&&!frame.rotated){const content=await frame.pdfPage.getTextContent();text=content.items.map(i=>i.str+(i.hasEOL?'\n':' ')).join('');}if(text.trim().length<20){const worker=await ocrWorker($('scan-language').value);const result=await worker.recognize(frame.canvas,{}, {text:true});text=result.data.text;}if(!closed){review(text);$('scan-progress').textContent=text.trim()?'识别完成，请核对内容':'未识别到文字，可旋转后重试';}}catch(e){if(!closed){$('scan-progress').textContent='识别失败';toast(e.message,true);}}finally{recognizing=false;scanProgress=()=>{};if(!closed){$('scan-recognize').disabled=false;$('scan-file').disabled=false;$('scan-page').disabled=doc.count<=1;$('modal-submit').disabled=false;}}};
  $('scan-rematch').onclick=()=>review($('scan-text').value);let selection='';$('scan-text').addEventListener('select',()=>{const el=$('scan-text');selection=el.value.slice(el.selectionStart,el.selectionEnd);});document.querySelector('.scan-fields').onclick=e=>{const id=e.target.dataset.scanLabel;if(id&&selection){document.querySelector(`[data-scan-field="${id}"]`).value=selection;window.scanDraftDirty=true;$('modal-submit').disabled=false;}};document.querySelector('.scan-fields').oninput=()=>{window.scanDraftDirty=true;$('modal-submit').disabled=false;};$('scan-text').oninput=()=>window.scanDraftDirty=true;
}
$('scan-open').onclick=scanDialog;
